    44	    };
    45	
    46	    const hidePopoverMenu = () => {
    47	        setPopupMenuVisible(false);
    48	    };
    49	
    50	    useEffect(() => {
    51	        if (!isBehindModal || !isPopupMenuVisible) {
    52	            return;
    53	        }
    54	        hidePopoverMenu();
    55	    }, [isBehindModal, isPopupMenuVisible]);
