    75	                            /* Keep the focus state on mWeb like we did on the native apps. */
    76	                            if (!Browser.isMobile()) {
    77	                                return;
    78	                            }
    79	                            e.preventDefault();
    80	                        }}
    81	                        ref={buttonRef}
    82	                        style={[styles.touchableButtonImage, iconStyles]}
    83	                        role={CONST.ROLE.BUTTON}
    84	                        accessibilityLabel={translate(iconTooltip)}
    85	                    >
    86	                        <Icon
    87	                            src={icon}
    88	                            fill={iconFill ?? isPopupMenuVisible ? theme.success : theme.icon}
    89	                        />
    90	                    </PressableWithoutFeedback>
    91	                </Tooltip>
    92	            </View>
    93	            <PopoverMenu
    94	                onClose={hidePopoverMenu}
    95	                isVisible={isPopupMenuVisible && !isBehindModal}
    96	                anchorPosition={anchorPosition}
    97	                anchorAlignment={anchorAlignment}
    98	                onItemSelected={hidePopoverMenu}
    99	                menuItems={menuItems}
   100	                withoutOverlay={!shouldOverlay}
   101	                shouldSetModalVisibility={shouldSetModalVisibility}
   102	                anchorRef={buttonRef}
   103	                shouldEnableNewFocusManagement
   104	            />
   105	        </>
   106	    );
   107	}
